import json
import re
from datetime import datetime, timezone, timedelta

current = _items[0].get("json") or {} if _items else {}
valid = current.get("valid", {})
normal = current.get("normal", {})
row = valid.get("row") or {}
data = valid.get("ingatkan") if isinstance(valid.get("ingatkan"), dict) else {}
def quote(value): return "'" + str(value).replace("'", "''") + "'"
try: amount = int(row.get("Nominal"))
except (TypeError, ValueError): amount = 0
if amount < 1 or amount >= 2**53: return [{"json": {"sql": None, "gagal": "nominal tidak valid"}}]
message_id = normal.get("messageId")
message_sql = str(message_id) if isinstance(message_id, int) and not isinstance(message_id, bool) else "null"
teks = " ".join(str(data.get("teks") or "").split())[:200]
pola = str(data.get("pola") or "").lower()
jam = str(data.get("jam") or "").strip()
cocok_jam = re.fullmatch(r"([01]?\d|2[0-3]):([0-5]\d)", jam)
tanggal = str(data.get("tanggal") or "").strip()
bulan_tgl = data.get("bulan_tgl")
pengingat = None
if teks and pola == "bulanan" and isinstance(bulan_tgl, int) and 1 <= bulan_tgl <= 28:
    pengingat = "public.rutin_tambah(" + quote(str(row.get("Keterangan") or teks)[:80]) + ", " + str(amount) + ", " + str(bulan_tgl) + ", " + quote(row.get("Jenis", "Pengeluaran")) + ", " + quote(row.get("Kategori", "Lainnya")) + ")"
elif teks and cocok_jam and pola in ("sekali", "harian"):
    jam_rapi = "%02d:%02d" % (int(cocok_jam.group(1)), int(cocok_jam.group(2)))
    if pola == "harian":
        pengingat = "public.ingatkan_tambah(" + quote(teks) + ", 'harian', null, '" + jam_rapi + "'::time)"
    else:
        if re.fullmatch(r"[1-9]\d{3}-\d{2}-\d{2}", tanggal):
            waktu = "('" + tanggal + " " + jam_rapi + "'::timestamp at time zone 'Asia/Jakarta')"
        else:
            waktu = "(((now() at time zone 'Asia/Jakarta')::date + case when (now() at time zone 'Asia/Jakarta')::time >= '" + jam_rapi + "'::time then 1 else 0 end) + '" + jam_rapi + "'::time) at time zone 'Asia/Jakarta'"
        pengingat = "public.ingatkan_tambah(" + quote(teks) + ", 'sekali', " + waktu + ", null)"
transaksi = "public.catat_transaksi(" + ", ".join([quote(row.get("Tanggal", "")) + "::date", quote(row.get("Jenis", "")), quote(row.get("Kategori", "")), str(amount), quote(row.get("Keterangan", "")), message_sql, quote(row.get("Dompet") or "")]) + ")"
if pengingat and bulan_tgl:
    sql = "select " + pengingat + " as output"
elif pengingat:
    sql = ("with t as (select * from " + transaksi + " limit 1), i as (select " + pengingat + " as pesan) "
           "select t.id, t.amount::float8 as amount, t.occurred_at, t.kind, t.category, t.note, (select pesan from i) as pesan, "
           "'Tercatat ' || t.id || E'\\n' || t.kind || ' ' || public.rupiah(t.amount) || E'\\n' || t.category || ' · ' || t.note || E'\\n\\n' || (select pesan from i) as output from t")
else:
    sql = "select id, amount::float8 as amount from " + transaksi
return [{"json": {"sql": sql, "route": normal.get("route"), "tanggal": row.get("Tanggal"), "jenis": row.get("Jenis"), "kategori": row.get("Kategori"), "nominal": amount, "keterangan": row.get("Keterangan"), "dompet": row.get("Dompet"), "ingatkan": pengingat is not None}}]

