import json
import re
from datetime import datetime, timezone, timedelta

current = _items[0].get("json") or {} if _items else {}
normal = current.get("normal", {})
text = str(normal.get("text") or "").lower()
def quote(value): return "'" + str(value).replace("'", "''") + "'"
def amount_of(value):
    if isinstance(value, bool): return None
    if isinstance(value, int): return value
    digits = re.sub(r"[^\d]", "", str(value or ""))
    try: return int(digits) if digits else None
    except ValueError: return None
def rupiah(value): return "Rp" + f"{value:,}".replace(",", ".")
def reply(message): return [{"json": {"sql": "select " + quote(message) + "::text as output"}}]
if re.search(r"\b(jangan|jgn)\b", text, re.I): return reply("Oke, tidak menghapus apa pun.")
kode_trx = re.search(r"\b(in|out)[- ]?(\d{1,6})\b", text, re.I)
if kode_trx:
    target = kode_trx.group(1).upper() + "-" + kode_trx.group(2).zfill(4)
    return [{"json": {"sql": "select public.hapus_transaksi(" + quote(target) + ") as output"}}]
rows = [item.get("json") or {} for item in _items if (item.get("json") or {}).get("ID_Transaksi")]
if not rows: return reply("Belum ada transaksi yang bisa dihapus.")
amount = None
match = re.search(r"rp\.?\s*([\d.]+)", text)
if match:
    digit = match.group(1).replace(".", "")
    amount = int(digit) if digit else None
if amount is None:
    match = re.search(r"([\d.,]+)\s*(jt|juta)\b", text)
    if match: amount = round(float(match.group(1).replace(",", ".")) * 1_000_000)
if amount is None:
    match = re.search(r"([\d.,]+)\s*(rb|ribu|k)\b", text)
    if match: amount = round(float(match.group(1).replace(",", ".")) * 1_000)
if amount is None:
    match = re.search(r"\b(\d{1,3}(?:\.\d{3})+)\b", text)
    if match: amount = int(match.group(1).replace(".", ""))
if amount is None:
    match = re.search(r"\b(\d{3,})\b", text)
    if match: amount = int(match.group(1))
stop = set("eh kamu tau ga gak nggak enggak untuk yang tadi dihapus hapus hapusin saja aja ya dong itu ini pengeluaran pemasukan transaksi mohon tolong bisa boleh kah dan di ke dari aku saya nya deh kan maksud maksudnya kok sih nih tuh barusan terakhir punya sedang lagi ada".split())
known = ["gaji", "makanan", "transportasi", "belanja", "tagihan", "hiburan", "lainnya"]
words = [w for w in re.sub(r"[^a-z0-9\s]", " ", text).split() if len(w) > 2 and w not in stop]
category = next((k for k in known if k in text), None)
if amount is None and not words: return [{"json": {"sql": "select public.hapus_transaksi(" + quote(rows[0]["ID_Transaksi"]) + ") as output"}}]
candidates = rows[:]
if category: candidates = [r for r in candidates if str(r.get("Kategori") or "").lower() == category]
if amount is not None:
    candidates = [r for r in candidates if str(r.get("Jenis") or "") != "Transfer" and amount_of(r.get("Nominal")) == amount]
    if not candidates: return reply("Tidak menemukan transaksi " + rupiah(amount) + ". Pakai /hapus ID kalau tahu kodenya.")
elif words:
    scored = [(r, sum(1 for w in words if w in str(r.get("Keterangan") or "").lower())) for r in candidates]
    scored = [(r, score) for r, score in scored if score > 0]
    scored.sort(key=lambda x: x[1], reverse=True)
    if not scored: return reply('Tidak menemukan transaksi yang cocok dengan "' + " ".join(words) + '". Sebutkan nominalnya, atau pakai /hapus ID.')
    best = scored[0][1]
    candidates = [r for r, score in scored if score == best]
if len(candidates) > 1:
    lines = [f"• {r.get('ID_Transaksi')} · {rupiah(amount_of(r.get('Nominal')) or 0)} · {r.get('Keterangan') or '-'} · {str(r.get('Tanggal') or '')[:10]}" for r in candidates[:4]]
    return reply("Maksud yang mana?\n" + "\n".join(lines) + "\n\nBalas /hapus " + str(candidates[0]["ID_Transaksi"]))
target = candidates[0] if candidates else (rows[0] if rows else None)
if not target: return reply("Belum ada transaksi yang bisa dihapus.")
return [{"json": {"sql": "select public.hapus_transaksi(" + quote(target["ID_Transaksi"]) + ") as output"}}]

import json
import re
from datetime import datetime, timezone, timedelta

def parse_json(value):
    if isinstance(value, dict): return value
    if not isinstance(value, str): return None
    start, end = value.find("{"), value.rfind("}")
    if start < 0 or end <= start: return None
    try: return json.loads(value[start:end + 1])
    except (ValueError, TypeError): return None
normal = (_items[0].get("json") or {}).get("normal", {}) if _items else {}
route = str(normal.get("route") or "")
transcript = str(normal.get("text") or "").strip()
current = _items[0].get("json", {}) if _items else {}
response = current
intent = current.get("niat") or {}
content = (response.get("message") or {}).get("content")
transaction = parse_json(content if content is not None else response.get("content"))
if isinstance(transaction, dict):
    acuan = (" " + str(transaction.get("keterangan") or "") + " " + transcript + " ").lower()
    if transaction.get("jenis") not in ("Pemasukan", "Pengeluaran"):
        if re.search(r"\b(beli|bayar|jajan|makan|minum|bensin|parkir|belanja|sewa|tagihan|listrik|pulsa|ongkos|tiket|kopi|kue|pizza|bakso|nasi|snack|rokok|obat|donasi)\b", acuan):
            transaction["jenis"] = "Pengeluaran"
        elif re.search(r"\b(gaji|bonus|masuk|terima|dapat|pendapatan|fee|honor|refund|jual)\b", acuan):
            transaction["jenis"] = "Pemasukan"
    if not transaction.get("mata_uang"):
        transaction["mata_uang"] = "IDR"
    if isinstance(transaction.get("nominal"), str):
        digit = re.sub(r"[^\d]", "", transaction.get("nominal"))
        transaction["nominal"] = int(digit) if digit else None
invalid = [{"json": {"valid": False, "tanyaAgen": route == "Suara", "output": "Belum tercatat. Kirim satu transaksi dengan jenis, keterangan, dan nominal rupiah yang jelas, misalnya “pengeluaran makan Rp25.000”, atau kirim ulang foto struk yang lebih jelas. Kalau maksud Anda bertanya, tulis saja pertanyaannya, misalnya “pengeluaran kemarin berapa?”." + (f"\n\nSaya dengar: “{transcript}”" if route == "Suara" and transcript else "")}}]
if not isinstance(transaction, dict) or transaction.get("jenis") not in ("Pemasukan", "Pengeluaran") or transaction.get("mata_uang") != "IDR": return invalid
amount = transaction.get("nominal")
if isinstance(amount, bool) or not isinstance(amount, int) or amount < 1 or amount >= 10**15: return invalid
date = transaction.get("tanggal")
timestamp = normal.get("received", "")
if date is not None:
    if not isinstance(date, str) or not re.fullmatch(r"[1-9]\d{3}-\d{2}-\d{2}", date): return invalid
    try: datetime.strptime(date, "%Y-%m-%d")
    except ValueError: return invalid
    if date[5:] == timestamp[5:10] and int(date[:4]) < int(timestamp[:4]) - 1:
        date = timestamp[:10]
    if date > timestamp[:10]: return invalid
    if date != timestamp[:10]: timestamp = date
desc = transaction.get("keterangan")
desc = re.sub(r"\s+", " ", desc).strip()[:200] if isinstance(desc, str) else ""
if not desc: return invalid
categories = ["Gaji", "Makanan", "Transportasi", "Belanja", "Tagihan", "Hiburan", "Lainnya"]
dompet = None
if route != "Foto":
    dompet = transaction.get("dompet") or intent.get("dompet")
dompet = re.sub(r"\s+", " ", dompet).strip()[:40] if isinstance(dompet, str) else None
row = {"Tanggal": timestamp, "Jenis": transaction["jenis"], "Kategori": transaction.get("kategori") if transaction.get("kategori") in categories else "Lainnya", "Nominal": amount, "Keterangan": desc, "Dompet": dompet}
pengingat_teks = re.sub(r"\s+", " ", str(transaction.get("ingatkan_teks") or "")).strip()[:200]
pola_pengingat = str(transaction.get("ingatkan_pola") or "").lower()
jam_pengingat = str(transaction.get("ingatkan_jam") or "").strip()
cocok_jam = re.fullmatch(r"([01]?\d|2[0-3]):([0-5]\d)", jam_pengingat)
tanggal_pengingat = transaction.get("ingatkan_tanggal")
if not (isinstance(tanggal_pengingat, str) and re.fullmatch(r"[1-9]\d{3}-\d{2}-\d{2}", tanggal_pengingat)):
    tanggal_pengingat = None
bulan_pengingat = transaction.get("ingatkan_bulan_tgl")
if isinstance(bulan_pengingat, bool) or not isinstance(bulan_pengingat, int) or not 1 <= bulan_pengingat <= 28: bulan_pengingat = None
ingatkan = None
if pengingat_teks:
    if pola_pengingat == "bulanan" and bulan_pengingat:
        ingatkan = {"teks": pengingat_teks, "pola": "bulanan", "bulan_tgl": bulan_pengingat}
    elif cocok_jam and pola_pengingat in ("sekali", "harian"):
        ingatkan = {"teks": pengingat_teks, "pola": pola_pengingat,
                    "jam": "%02d:%02d" % (int(cocok_jam.group(1)), int(cocok_jam.group(2))),
                    "tanggal": tanggal_pengingat}
return [{"json": {"valid": True, "row": row, "ingatkan": ingatkan}}]

