const esc = (v) => v === null || v === undefined ? 'null' : "'" + String(v).replace(/'/g, "''") + "'";
const workflowName = "Expense Tracker - Pemrosesan";
return $input.all().map((item) => {
  const m = (item && item.json) || {};
  const p = m.result && typeof m.result === 'object' ? m.result : m;
  const chatId = p.chat && p.chat.id ? p.chat.id : null;
  const messageId = p.message_id === undefined ? null : p.message_id;
  const text = p.text === undefined ? '' : p.text;
  const executionId = $execution && $execution.id ? $execution.id : '';
  const sql = "insert into public.conversation_logs (chat_id, message_id, direction, kind, text, intent, workflow, execution_id) values (" + (chatId === null ? "null" : chatId) + ", " + (messageId === null ? "null" : messageId) + ", 'out', 'text', " + esc(text) + ", null, " + esc(workflowName) + ", " + esc(executionId) + ")";
  return { json: { sql } };
});
